mapper.select:
select pp.supplier_id, s.name as supplierName, ppd.currency, ppd.tax_price as taxPrice, ppd.tax_rate * 100 as taxRate, ppd.min_qty as minQty, ppd.max_qty as maxQty, ppd.delivery_day as deliveryDay from purchase_price pp left join purchase_price_detail ppd on pp.id = ppd.purchase_price_id and ppd.is_deleted = false left join supplier s on pp.supplier_id = s.id and s.is_deleted = false
pp.is_deleted = false and pp.approve_status = 'approve' and ppd.disabled = false and now() >= ppd.effective_date
and ppd.sku_id = #{params.skuId}
and ppd.max_qty >= #{params.purchaseQty} and #{params.purchaseQty} >= ppd.min_qty
and pp.supplier_id = #{params.supplierId}
